import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast over a shared Steiner-style tree that minimizes the union of
    edges used (the true cost driver: an edge's cost is paid once and shared by
    every destination/partition traversing it). A zero-marginal-cost greedy
    heuristic attaches destinations one at a time, with edges already in the
    tree made free; every possible first destination is tried and the cheapest
    tree kept. A fixpoint refinement then re-routes each destination over the
    final free trunk (replacement paths stay inside the trunk, so the union
    only shrinks). All partitions reuse the same per-dst edge list, so no
    transfer is ever repeated."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    def dijkstra(g):
        try:
            return nx.single_source_dijkstra(g, src, weight="cost")
        except Exception:
            return {}, {}

    def greedy_tree(first=None):
        # attach dsts one at a time; edges already chosen become free
        w = h.copy()
        paths = {}
        remaining = [d for d in dsts if d != src]
        if first is not None and first in remaining:
            remaining.remove(first)
            remaining.insert(0, first)
        while remaining:
            dist, spaths = dijkstra(w)
            cand = [(dist[d], d) for d in remaining if d in dist]
            if cand:
                d = min(cand)[1]
                p = spaths[d]
            else:
                # unreachable in the priced graph: fall back to any hop path
                d = remaining[0]
                try:
                    p = nx.shortest_path(G, src, d)
                except Exception:
                    remaining.remove(d)
                    continue
            paths[d] = p
            remaining.remove(d)
            for i in range(len(p) - 1):
                u, v = p[i], p[i + 1]
                if w.has_edge(u, v) and w[u][v].get("cost"):
                    w[u][v]["cost"] = 0
        return paths

    def refine(paths):
        # re-route every dst over the current shared trunk until fixpoint
        for _ in range(len(paths) + 2):
            union = set()
            for p in paths.values():
                for i in range(len(p) - 1):
                    union.add((p[i], p[i + 1]))
            w = h.copy()
            for u, v in union:
                if w.has_edge(u, v):
                    w[u][v]["cost"] = 0
            _, spaths = dijkstra(w)
            changed = False
            for d in list(paths):
                if d in spaths and spaths[d] != paths[d]:
                    paths[d] = spaths[d]
                    changed = True
            if not changed:
                break
        return paths

    def union_cost(paths):
        seen = set()
        total = 0.0
        for p in paths.values():
            for i in range(len(p) - 1):
                e = (p[i], p[i + 1])
                if e not in seen:
                    seen.add(e)
                    c = h[e[0]][e[1]].get("cost") if h.has_edge(*e) else None
                    total += c if c is not None else 0.0
        return total

    # candidate 0: per-dst independent shortest paths (single Dijkstra)
    best, best_cost = None, None
    dist, spaths = dijkstra(h)
    indep = {d: spaths[d] for d in dsts if d != src and d in spaths}
    if indep and len(indep) == len([d for d in dsts if d != src]):
        best, best_cost = dict(indep), union_cost(indep)

    # candidates 1..n: greedy Steiner trees, one per possible first dst
    for first in [None] + [d for d in dsts if d != src]:
        paths = refine(greedy_tree(first))
        if not paths:
            continue
        c = union_cost(paths)
        if best is None or c < best_cost:
            best, best_cost = paths, c

    if best is None:
        best = {}

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    for dst in dsts:
        p = best.get(dst)
        if p is None:
            if dst == src:
                p = [src]
            else:
                try:
                    p = nx.shortest_path(G, src, dst)
                except Exception:
                    continue
        edge_list = [[p[i], p[i + 1], G[p[i]][p[i + 1]]]
                     for i in range(len(p) - 1)]
        for j in range(num_partitions):
            bc_topology.set_dst_partition_paths(dst, j, list(edge_list))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

